// ==============================
// GET RAW DATA FROM PREVIOUS NODES
// ==============================

const makeData =
  $('Make.com Information').first().json.organization;

const voiceflowData =
  $('Voiceflow Analytics').first().json.result.items;

const vapiData =
  $('Vapi Analytics').first().json.result;


// ==============================
// MAKE.COM ANALYSIS
// ==============================

const makeReport = {
  plan: makeData.productName,
  operationsLimit: Number(makeData.license.operations || 0),
  operationsUsed: Number(makeData.operations || 0),
  operationsRemaining: Number(makeData.unusedOperations || 0),

  creditsUsed:
    Number(makeData.centicreditsConsumed || 0) / 100,

  creditsRemaining:
    Number(makeData.unusedCenticredits || 0) / 100,

  transferUsedMB:
    (
      Number(makeData.transfer || 0) /
      1024 /
      1024
    ).toFixed(2),

  activeScenarios: makeData.activeScenarios,
  activeApps: makeData.activeApps,

  nextReset: makeData.nextReset
};


// ==============================
// VOICEFLOW ANALYSIS
// ==============================

let totalAI = 0;
let totalInteractions = 0;

const modelStats = {};
const interactionStats = {};
const dailyUsage = {};

for (const item of voiceflowData) {

  const date = item.period.split("T")[0];

  // DAILY USAGE
  if (!dailyUsage[date]) {
    dailyUsage[date] = 0;
  }

  dailyUsage[date] += item.count;

  // AI USAGE
  if (
    item.type === "llm-input" ||
    item.type === "llm-output"
  ) {

    totalAI += item.count;

    if (!modelStats[item.model]) {
      modelStats[item.model] = {
        input: 0,
        output: 0
      };
    }

    if (item.type === "llm-input") {
      modelStats[item.model].input += item.count;
    }

    if (item.type === "llm-output") {
      modelStats[item.model].output += item.count;
    }
  }

  // INTERACTIONS
  if (item.type === "interaction") {

    totalInteractions += item.count;

    if (!interactionStats[item.model]) {
      interactionStats[item.model] = 0;
    }

    interactionStats[item.model] += item.count;
  }
}


// ==============================
// MOST USED MODEL
// ==============================

let mostUsedModel = "";
let highestModelUsage = 0;

for (const model in modelStats) {

  const total =
    modelStats[model].input +
    modelStats[model].output;

  if (total > highestModelUsage) {
    highestModelUsage = total;
    mostUsedModel = model;
  }
}


// ==============================
// HIGHEST USAGE DAY
// ==============================

let highestUsageDay = "";
let highestUsage = 0;

for (const day in dailyUsage) {

  if (dailyUsage[day] > highestUsage) {
    highestUsage = dailyUsage[day];
    highestUsageDay = day;
  }
}


// ==============================
// FORMAT MODEL TABLE
// ==============================

const aiBreakdown = [];

for (const model in modelStats) {

  aiBreakdown.push({
    model,
    inputUsage: modelStats[model].input,
    outputUsage: modelStats[model].output,
    total:
      modelStats[model].input +
      modelStats[model].output
  });
}


// ==============================
// FORMAT INTERACTION TABLE
// ==============================

const interactionBreakdown = [];

for (const source in interactionStats) {

  interactionBreakdown.push({
    source,
    count: interactionStats[source]
  });
}


// ==============================
// FORMAT DAILY TREND
// ==============================

const dailyTrend = [];

for (const day in dailyUsage) {

  dailyTrend.push({
    date: day,
    totalUsage: dailyUsage[day]
  });
}


// ==============================
// VOICEFLOW FINAL REPORT
// ==============================

const voiceflowReport = {
  totalAIOperations: totalAI,
  totalInteractions,
  mostUsedModel,
  highestUsageDay,
  aiBreakdown,
  interactionBreakdown,
  dailyTrend,

  notes: [
    "Counts represent usage events, not exact billing.",
    "Voiceflow API does not expose exact USD costs.",
    "AI usage estimated using llm-input and llm-output."
  ]
};


// ==============================
// VAPI ANALYSIS
// ==============================

let totalCalls = 0;
let totalDuration = 0;
let totalCost = 0;

let llmCost = 0;
let sttCost = 0;
let ttsCost = 0;
let transportCost = 0;
let vapiCost = 0;

const assistantBreakdown = [];

for (const item of vapiData) {

  totalCalls += Number(item.totalCalls || 0);

  totalDuration += Number(item.totalDuration || 0);

  totalCost += Number(item.totalCost || 0);

  llmCost += Number(item.llmCost || 0);

  sttCost += Number(item.sttCost || 0);

  ttsCost += Number(item.ttsCost || 0);

  transportCost += Number(item.transportCost || 0);

  vapiCost += Number(item.vapiCost || 0);

  assistantBreakdown.push({
    assistantId: item.assistantId,
    totalCalls: Number(item.totalCalls || 0),
    totalDuration: Number(item.totalDuration || 0).toFixed(2),
    avgDuration: Number(item.avgDuration || 0).toFixed(2),
    totalCost: Number(item.totalCost || 0).toFixed(4)
  });
}


// ==============================
// VAPI FINAL REPORT
// ==============================

const vapiReport = {

  totalCalls,

  totalDurationMinutes:
    totalDuration.toFixed(2),

  avgCallDuration:
    totalCalls > 0
      ? (totalDuration / totalCalls).toFixed(2)
      : 0,

  totalCost:
    totalCost.toFixed(4),

  costBreakdown: {
    llmCost: llmCost.toFixed(4),
    sttCost: sttCost.toFixed(4),
    ttsCost: ttsCost.toFixed(4),
    transportCost:
      transportCost.toFixed(4),
    vapiCost:
      vapiCost.toFixed(4)
  },

  assistantBreakdown
};


// ==============================
// FINAL EXECUTIVE SUMMARY
// ==============================

const executiveSummary = {

  make: {
    operationsUsed:
      makeReport.operationsUsed,

    creditsUsed:
      makeReport.creditsUsed
  },

  voiceflow: {
    aiOperations:
      voiceflowReport.totalAIOperations,

    interactions:
      voiceflowReport.totalInteractions
  },

  vapi: {
    totalCalls:
      vapiReport.totalCalls,

    totalCost:
      vapiReport.totalCost
  }
};


// ==============================
// RETURN FINAL STRUCTURED REPORT
// ==============================

return [
  {
    json: {
      generatedAt:
        new Date().toISOString(),

      executiveSummary:
        executiveSummary || {},

      makeReport:
        makeReport || {},

      voiceflowReport:
        voiceflowReport || {},

      vapiReport:
        vapiReport || {}
    }
  }
];

// ─────────────────────────────────────────────
// Budget Threshold Monitoring Engine
// Input:
// {
//   generatedAt,
//   executiveSummary,
//   makeReport,
//   voiceflowReport,
//   vapiReport
// }
// ─────────────────────────────────────────────

const data = $input.first().json;

// ─────────────────────────────────────────────
// DATE CALCULATIONS
// ─────────────────────────────────────────────

const now = new Date();

const dayOfMonth = now.getDate();

const daysInMonth = new Date(
  now.getFullYear(),
  now.getMonth() + 1,
  0
).getDate();

const projectionMultiplier = daysInMonth / dayOfMonth;

// ─────────────────────────────────────────────
// THRESHOLD CONFIG
// ─────────────────────────────────────────────

const thresholds = {

  make: {
    operationsLimit: 1000,
    warning: 70,
    high: 85,
    critical: 95
  },

  voiceflow: {
    aiOpsLimit: 5000,
    interactionsLimit: 2000,
    warning: 75,
    high: 90,
    critical: 100
  },

  vapi: {
    monthlyBudget: 10,
    warning: 70,
    high: 90,
    critical: 100
  }

};

// ─────────────────────────────────────────────
// HELPER FUNCTIONS
// ─────────────────────────────────────────────

function calculatePercentage(used, limit) {
  if (!limit || limit === 0) return 0;
  return Number(((used / limit) * 100).toFixed(2));
}

function getSeverity(percent, config) {

  if (percent >= config.critical) {
    return "CRITICAL";
  }

  if (percent >= config.high) {
    return "HIGH";
  }

  if (percent >= config.warning) {
    return "WARNING";
  }

  return "NORMAL";
}

// ─────────────────────────────────────────────
// MAKE.COM ANALYSIS
// ─────────────────────────────────────────────

const makeOpsUsed =
  Number(data.makeReport?.operationsUsed || 0);

const makeCreditsUsed =
  Number(data.makeReport?.creditsUsed || 0);

const makeProjectedOps =
  Number((makeOpsUsed * projectionMultiplier).toFixed(2));

const makeUsagePercent =
  calculatePercentage(
    makeOpsUsed,
    thresholds.make.operationsLimit
  );

const makeSeverity =
  getSeverity(makeUsagePercent, thresholds.make);

// ─────────────────────────────────────────────
// VOICEFLOW ANALYSIS
// ─────────────────────────────────────────────

const vfAiOps =
  Number(data.voiceflowReport?.totalAIOperations || 0);

const vfInteractions =
  Number(data.voiceflowReport?.totalInteractions || 0);

const vfProjectedOps =
  Number((vfAiOps * projectionMultiplier).toFixed(2));

const vfProjectedInteractions =
  Number((vfInteractions * projectionMultiplier).toFixed(2));

const vfOpsPercent =
  calculatePercentage(
    vfAiOps,
    thresholds.voiceflow.aiOpsLimit
  );

const vfInteractionPercent =
  calculatePercentage(
    vfInteractions,
    thresholds.voiceflow.interactionsLimit
  );

const vfSeverity =
  getSeverity(
    Math.max(vfOpsPercent, vfInteractionPercent),
    thresholds.voiceflow
  );

// ─────────────────────────────────────────────
// VAPI ANALYSIS
// ─────────────────────────────────────────────

const vapiTotalCost =
  Number(data.vapiReport?.totalCost || 0);

const vapiCalls =
  Number(data.vapiReport?.totalCalls || 0);

const vapiProjectedCost =
  Number(
    (vapiTotalCost * projectionMultiplier).toFixed(2)
  );

const vapiUsagePercent =
  calculatePercentage(
    vapiTotalCost,
    thresholds.vapi.monthlyBudget
  );

const vapiSeverity =
  getSeverity(vapiUsagePercent, thresholds.vapi);

// ─────────────────────────────────────────────
// OVERALL SEVERITY
// ─────────────────────────────────────────────

const severityOrder = {
  NORMAL: 0,
  WARNING: 1,
  HIGH: 2,
  CRITICAL: 3
};

const allSeverities = [
  makeSeverity,
  vfSeverity,
  vapiSeverity
];

let overallSeverity = "NORMAL";

for (const sev of allSeverities) {

  if (
    severityOrder[sev] >
    severityOrder[overallSeverity]
  ) {
    overallSeverity = sev;
  }

}

// ─────────────────────────────────────────────
// SHOULD ALERT?
// ─────────────────────────────────────────────

const shouldAlert =
  overallSeverity !== "NORMAL";

// ─────────────────────────────────────────────
// BUILD ALERTS ARRAY
// ─────────────────────────────────────────────

const alerts = [];

if (makeSeverity !== "NORMAL") {

  alerts.push({
    platform: "Make.com",
    severity: makeSeverity,
    metric: "Operations Usage",
    current: makeOpsUsed,
    projected: makeProjectedOps,
    limit: thresholds.make.operationsLimit,
    usagePercent: makeUsagePercent
  });

}

if (vfSeverity !== "NORMAL") {

  alerts.push({
    platform: "Voiceflow",
    severity: vfSeverity,
    metric: "AI Operations",
    current: vfAiOps,
    projected: vfProjectedOps,
    limit: thresholds.voiceflow.aiOpsLimit,
    usagePercent: vfOpsPercent
  });

}

if (vapiSeverity !== "NORMAL") {

  alerts.push({
    platform: "Vapi",
    severity: vapiSeverity,
    metric: "Monthly Cost",
    current: vapiTotalCost,
    projected: vapiProjectedCost,
    limit: thresholds.vapi.monthlyBudget,
    usagePercent: vapiUsagePercent
  });

}

// ─────────────────────────────────────────────
// FINAL OUTPUT
// ─────────────────────────────────────────────

return [
  {
    json: {

      generatedAt: now.toISOString(),

      overallSeverity,

      shouldAlert,

      summary: {

        make: {
          operationsUsed: makeOpsUsed,
          creditsUsed: makeCreditsUsed,
          projectedOperations: makeProjectedOps,
          usagePercent: makeUsagePercent,
          severity: makeSeverity
        },

        voiceflow: {
          aiOperations: vfAiOps,
          interactions: vfInteractions,
          projectedOperations: vfProjectedOps,
          projectedInteractions: vfProjectedInteractions,
          usagePercent: vfOpsPercent,
          severity: vfSeverity
        },

        vapi: {
          totalCalls: vapiCalls,
          totalCost: vapiTotalCost,
          projectedCost: vapiProjectedCost,
          usagePercent: vapiUsagePercent,
          severity: vapiSeverity
        }

      },

      alerts

    }
  }
];
